entries[405807] = { ["name"] = "Shaohao's Lesson - Anger", ["text"] = "Instant\nEach time you cast Sheilun's Gift, you learn one of Shaohao's Lessons for up to 30 sec, with the duration based on how many clouds of mist are consumed.\n\nLesson of Doubt : Your spells and abilities deal up to 40% more healing and damage to targets, based on their current health.\n\nLesson of Despair : Your Critical Strike is increased by 30% while above 50% health.\n\nLesson of Fear : Decreases your damage taken by 15% and increases your Haste by 20%.\n\nLesson of Anger : 25% of the damage or healing you deal is duplicated every 4 sec." }
